def add(sector,title,topic,env,mechanism,states,shots,positions,labels,inputs):
 parts=[v.split('|') for v in [states,shots,positions,labels]];assert all(len(v)==4 for v in parts),title
 slug=''.join(c for c in unicodedata.normalize('NFKD',title.lower()) if not unicodedata.combining(c)).replace(',','').replace(' ','-')
 direction={'structure':NAMES[sector]+' · '+mechanism.replace('_',' '),'labels':parts[3],'camera':parts[1],'blocking':parts[2],'graphicEvolution':parts[0],'typography':'Tipografia editorial de dados: sans contemporânea com numerais tabulares e serifa pontual; hierarquia clara, títulos curtos, eixos e unidades legíveis no celular. Cor indica função, não decoração.','layerOrder':['original_environment','explanatory_element_behind','original_presenter_or_observed_hands','explanatory_foreground'],'layerPolicy':'Construção ligada à fala e ação observadas. Contato e oclusão precisam de máscaras temporais e âncoras verificadas; telas e dados editáveis.','sourceTimes':None,'motionValidated':False}
 ROWS.append({'id':'explicador-'+sector+'-'+slug,'name':title,'sector':sector,'sectorName':NAMES[sector],'environment':env,'topic':topic,'mechanism':mechanism,'states':parts[0],'variantIndex':len(ROWS),'requiredInputs':inputs.split('|'),'domain':{'kind':'business_education','profile':NAMES[sector],'purpose':topic,'sourceVerificationRequired':True,'fictionalReferenceOnly':True,'metricsRequirePeriodDefinitionAndSource':True,'simulatedInterfacesAreNotLive':True},'customDirection':direction})
